// InitWithDBType initializes a new Project record with database context and type.
// db can be *sql.DB or *sql.Tx. There is no Init without the type: the type decides the SQL
// placeholders, and a default (SQLite) silently broke code on PostgreSQL.
func (t *Project) InitWithDBType(db database.Executor, company string, dbType database.DBType) {
	t.db = db
	t.company = company
	t.dbType = dbType
	t.oldValues = nil // Fresh record, no old values
	t.applyDefaults()
}

// InitRecord initializes a new, not yet inserted record (OnNewRecord).
// The base implementation applies the YAML default values; wrappers can override
// it to supply further defaults (call the base implementation first).
func (t *Project) InitRecord() {
	t.applyDefaults()
}

// applyDefaults assigns the YAML default values and auto timestamps
func (t *Project) applyDefaults() {
}

// StoreOldValues stores current field values for change detection
// Call this after loading a record from the database
func (t *Project) StoreOldValues() {
	t.oldValues = projectFields.OldValues(t.fieldRef)
}

// OldValue returns a field's value as last read from or written to the database (
// xRec), e.g. the old key in OnRename; nil when the record was not loaded.
func (t *Project) OldValue(fieldName string) interface{} {
	return t.oldValues[fieldName]
}

// XRec returns the record as it was last read from or written to the database (classic xRec),
// in the same database and company: xRec := rec.XRec(); if rec.No != xRec.No { … }. For a new
// record (never read) it is a blank record with the definition's defaults.
func (t *Project) XRec() *Project {
	x := &Project{db: t.db, company: t.company, dbType: t.dbType, temp: t.temp}
	x.InitRecord()
	projectFields.SetOldValues(x.fieldRef, t.oldValues)
	return x
}

// NewProject returns a Project record in the database and company of another
// record (from) — a classic Record variable: glAcc := gtables.NewGLAccount(rec)
func NewProject(from tables.Source) *Project {
	rec := &Project{}
	rec.InitWithDBType(from.GetDB(), from.GetCompany(), from.GetDBType())
	return rec
}

// IsGlobal reports whether the table is global (no company prefix, e.g. User, Company)
func (t *Project) IsGlobal() bool {
	return false
}

// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *Project) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *Project) Get(primaryKey interface{}) bool {
	// A composite primary key (map[string]interface{}, values also as text)
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		key := projectFields.KeyFromMap(pkMap)
		return t.GetByPK(key[0].(types.Code))
	}
	// The primary key itself (a table with one primary key field)
	if key, ok := projectFields.KeyFromValue(primaryKey); ok {
		return t.GetByPK([]any{key}[0].(types.Code))
	}

	fmt.Printf("Error: Invalid primary key type for Project.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *Project) GetByPK(no types.Code) bool {
	// Collect arguments for query
	args := []interface{}{
		no,
	}
	return t.rec().Get(args)
}

// Insert inserts the record into the database
func (t *Project) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ProjectTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.No,
		t.Search_description,
		t.Description,
		t.Description_2,
		t.Bill_to_customer_no,
		t.Creation_date,
		t.Starting_date,
		t.Ending_date,
		t.Completion_date,
		t.Project_posting_date,
		t.Recognition_date,
		t.Completion_percent,
		t.Status,
		t.Person_responsible,
		t.Dimension_1_code,
		t.Dimension_2_code,
		t.Project_posting_group,
		t.Blocked,
		t.Recognition_method,
		t.Last_date_modified,
		t.Application_method,
		t.Project_usage_posting,
		t.Picture,
		t.No_series,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (no, search_description, description, description_2, bill_to_customer_no, creation_date, starting_date, ending_date, completion_date, project_posting_date, recognition_date, completion_percent, status, person_responsible, dimension_1_code, dimension_2_code, project_posting_group, blocked, recognition_method, last_date_modified, application_method, project_usage_posting, picture, no_series) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Project: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(ProjectTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *Project) InsertAll(records []*Project, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.No,
			r.Search_description,
			r.Description,
			r.Description_2,
			r.Bill_to_customer_no,
			r.Creation_date,
			r.Starting_date,
			r.Ending_date,
			r.Completion_date,
			r.Project_posting_date,
			r.Recognition_date,
			r.Completion_percent,
			r.Status,
			r.Person_responsible,
			r.Dimension_1_code,
			r.Dimension_2_code,
			r.Project_posting_group,
			r.Blocked,
			r.Recognition_method,
			r.Last_date_modified,
			r.Application_method,
			r.Project_usage_posting,
			r.Picture,
			r.No_series,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ProjectTableName)
	columns := []string{"no", "search_description", "description", "description_2", "bill_to_customer_no", "creation_date", "starting_date", "ending_date", "completion_date", "project_posting_date", "recognition_date", "completion_percent", "status", "person_responsible", "dimension_1_code", "dimension_2_code", "project_posting_group", "blocked", "recognition_method", "last_date_modified", "application_method", "project_usage_posting", "picture", "no_series"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *Project) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ProjectTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			setClauses = append(setClauses, "no = ?")
			values = append(values, t.No)
		}
		if t.hasFieldChanged("search_description") {
			setClauses = append(setClauses, "search_description = ?")
			values = append(values, t.Search_description)
		}
		if t.hasFieldChanged("description") {
			setClauses = append(setClauses, "description = ?")
			values = append(values, t.Description)
		}
		if t.hasFieldChanged("description_2") {
			setClauses = append(setClauses, "description_2 = ?")
			values = append(values, t.Description_2)
		}
		if t.hasFieldChanged("bill_to_customer_no") {
			setClauses = append(setClauses, "bill_to_customer_no = ?")
			values = append(values, t.Bill_to_customer_no)
		}
		if t.hasFieldChanged("creation_date") {
			setClauses = append(setClauses, "creation_date = ?")
			values = append(values, t.Creation_date)
		}
		if t.hasFieldChanged("starting_date") {
			setClauses = append(setClauses, "starting_date = ?")
			values = append(values, t.Starting_date)
		}
		if t.hasFieldChanged("ending_date") {
			setClauses = append(setClauses, "ending_date = ?")
			values = append(values, t.Ending_date)
		}
		if t.hasFieldChanged("completion_date") {
			setClauses = append(setClauses, "completion_date = ?")
			values = append(values, t.Completion_date)
		}
		if t.hasFieldChanged("project_posting_date") {
			setClauses = append(setClauses, "project_posting_date = ?")
			values = append(values, t.Project_posting_date)
		}
		if t.hasFieldChanged("recognition_date") {
			setClauses = append(setClauses, "recognition_date = ?")
			values = append(values, t.Recognition_date)
		}
		if t.hasFieldChanged("completion_percent") {
			setClauses = append(setClauses, "completion_percent = ?")
			values = append(values, t.Completion_percent)
		}
		if t.hasFieldChanged("status") {
			setClauses = append(setClauses, "status = ?")
			values = append(values, t.Status)
		}
		if t.hasFieldChanged("person_responsible") {
			setClauses = append(setClauses, "person_responsible = ?")
			values = append(values, t.Person_responsible)
		}
		if t.hasFieldChanged("dimension_1_code") {
			setClauses = append(setClauses, "dimension_1_code = ?")
			values = append(values, t.Dimension_1_code)
		}
		if t.hasFieldChanged("dimension_2_code") {
			setClauses = append(setClauses, "dimension_2_code = ?")
			values = append(values, t.Dimension_2_code)
		}
		if t.hasFieldChanged("project_posting_group") {
			setClauses = append(setClauses, "project_posting_group = ?")
			values = append(values, t.Project_posting_group)
		}
		if t.hasFieldChanged("blocked") {
			setClauses = append(setClauses, "blocked = ?")
			values = append(values, t.Blocked)
		}
		if t.hasFieldChanged("recognition_method") {
			setClauses = append(setClauses, "recognition_method = ?")
			values = append(values, t.Recognition_method)
		}
		if t.hasFieldChanged("last_date_modified") {
			setClauses = append(setClauses, "last_date_modified = ?")
			values = append(values, t.Last_date_modified)
		}
		if t.hasFieldChanged("application_method") {
			setClauses = append(setClauses, "application_method = ?")
			values = append(values, t.Application_method)
		}
		if t.hasFieldChanged("project_usage_posting") {
			setClauses = append(setClauses, "project_usage_posting = ?")
			values = append(values, t.Project_usage_posting)
		}
		if t.hasFieldChanged("picture") {
			setClauses = append(setClauses, "picture = ?")
			values = append(values, t.Picture)
		}
		if t.hasFieldChanged("no_series") {
			setClauses = append(setClauses, "no_series = ?")
			values = append(values, t.No_series)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "search_description = ?")
		values = append(values, t.Search_description)
		setClauses = append(setClauses, "description = ?")
		values = append(values, t.Description)
		setClauses = append(setClauses, "description_2 = ?")
		values = append(values, t.Description_2)
		setClauses = append(setClauses, "bill_to_customer_no = ?")
		values = append(values, t.Bill_to_customer_no)
		setClauses = append(setClauses, "creation_date = ?")
		values = append(values, t.Creation_date)
		setClauses = append(setClauses, "starting_date = ?")
		values = append(values, t.Starting_date)
		setClauses = append(setClauses, "ending_date = ?")
		values = append(values, t.Ending_date)
		setClauses = append(setClauses, "completion_date = ?")
		values = append(values, t.Completion_date)
		setClauses = append(setClauses, "project_posting_date = ?")
		values = append(values, t.Project_posting_date)
		setClauses = append(setClauses, "recognition_date = ?")
		values = append(values, t.Recognition_date)
		setClauses = append(setClauses, "completion_percent = ?")
		values = append(values, t.Completion_percent)
		setClauses = append(setClauses, "status = ?")
		values = append(values, t.Status)
		setClauses = append(setClauses, "person_responsible = ?")
		values = append(values, t.Person_responsible)
		setClauses = append(setClauses, "dimension_1_code = ?")
		values = append(values, t.Dimension_1_code)
		setClauses = append(setClauses, "dimension_2_code = ?")
		values = append(values, t.Dimension_2_code)
		setClauses = append(setClauses, "project_posting_group = ?")
		values = append(values, t.Project_posting_group)
		setClauses = append(setClauses, "blocked = ?")
		values = append(values, t.Blocked)
		setClauses = append(setClauses, "recognition_method = ?")
		values = append(values, t.Recognition_method)
		setClauses = append(setClauses, "last_date_modified = ?")
		values = append(values, t.Last_date_modified)
		setClauses = append(setClauses, "application_method = ?")
		values = append(values, t.Application_method)
		setClauses = append(setClauses, "project_usage_posting = ?")
		values = append(values, t.Project_usage_posting)
		setClauses = append(setClauses, "picture = ?")
		values = append(values, t.Picture)
		setClauses = append(setClauses, "no_series = ?")
		values = append(values, t.No_series)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.No)
	}
	// Renamed key fields that other tables refer to (Rename): carried over below
	type renamedKey struct {
		field    string
		old, new interface{}
	}
	var renamed []renamedKey
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			renamed = append(renamed, renamedKey{"no", t.oldValues["no"], t.No})
		}
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Project: %v\n", err)
		return false
	}
	// A temporary record's rename stays in the record: other tables are not changed
	for _, r := range renamed {
		if t.temp != nil {
			break
		}
		if err := t.renameReferences(r.field, r.old, r.new); err != nil {
			fmt.Printf("Error: Failed to rename references to Project: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *Project) hasFieldChanged(fieldName string) bool {
	return projectFields.Changed(t.fieldRef, t.oldValues, fieldName)
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *Project) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *Project) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"no": {{"Comment_Line", false, "no", "table_name", 5}, {"Gen_Journal_Line", false, "project_no", "", 0}, {"G_L_Entry", false, "project_no", "", 0}, {"Project_Budget_Entry", false, "project_no", "", 0}, {"Project_Budget_Line", false, "project_no", "", 0}, {"Project_Journal_Line", false, "project_no", "", 0}, {"Project_Ledger_Entry", false, "project_no", "", 0}, {"Purch_Cr_Memo_Hdr", false, "project_no", "", 0}, {"Purch_Cr_Memo_Line", false, "project_no", "", 0}, {"Purch_Inv_Header", false, "project_no", "", 0}, {"Purch_Inv_Line", false, "project_no", "", 0}, {"Purch_Rcpt_Header", false, "project_no", "", 0}, {"Purch_Rcpt_Line", false, "project_no", "", 0}, {"Purchase_Header", false, "project_no", "", 0}, {"Purchase_Line", false, "project_no", "", 0}, {"Res_Journal_Line", false, "project_no", "", 0}, {"Res_Ledger_Entry", false, "project_no", "", 0}, {"Resource_Price", false, "project_no", "", 0}, {"Resource_Price_Change", false, "project_no", "", 0}, {"Sales_Cr_Memo_Header", false, "project_no", "", 0}, {"Sales_Cr_Memo_Line", false, "project_no", "", 0}, {"Sales_Header", false, "project_no", "", 0}, {"Sales_Invoice_Header", false, "project_no", "", 0}, {"Sales_Invoice_Line", false, "project_no", "", 0}, {"Sales_Line", false, "project_no", "", 0}, {"Sales_Shipment_Header", false, "project_no", "", 0}, {"Sales_Shipment_Line", false, "project_no", "", 0}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// refuseDeleteWhenUsed: a record still refers to this one
func (t *Project) refuseDeleteWhenUsed() error {
	return tables.RefuseDeleteWhenUsed(t.exec(), t.dbType, tables.DeletedRecord{
		Table: ProjectTableName, Global: false, Company: t.company,
		KeyColumn: "no", Key: t.No, KeyText: fmt.Sprint(t.No),
	}, []tables.Reference{
		{Table: "Comment_Line", Column: "no", CondColumn: "table_name", CondValue: 5},
		{Table: "Gen_Journal_Line", Column: "project_no"},
		{Table: "Project_Budget_Entry", Column: "project_no"},
		{Table: "Project_Budget_Line", Column: "project_no"},
		{Table: "Project_Journal_Line", Column: "project_no"},
		{Table: "Purchase_Header", Column: "project_no"},
		{Table: "Purchase_Line", Column: "project_no"},
		{Table: "Res_Journal_Line", Column: "project_no"},
		{Table: "Resource_Price", Column: "project_no"},
		{Table: "Resource_Price_Change", Column: "project_no"},
		{Table: "Sales_Header", Column: "project_no"},
		{Table: "Sales_Line", Column: "project_no"},
	})
}

// Delete removes the record from the database
func (t *Project) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
		// Refused while a record still refers to this one (refuse_delete_when_used)
		if t.temp == nil {
			if err := t.refuseDeleteWhenUsed(); err != nil {
				t.triggerErr = err
				return false
			}
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ProjectTableName)

	// Collect arguments for DELETE
	args := []interface{}{
		t.No,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`DELETE FROM "%s" WHERE 1=1 AND no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	_, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete Project: %v\n", err)
		return false
	}
	return true
}

